# HiTechnic NXT Color Sensor V2 (NCO1038) por I2C con Pybricks 2.0 en ev3dev.
# Dirección 0x02 de 8 bits = 0x01 de 7 bits. Registro 0x41: modo 0 activo, 1 pasivo, 3 crudo.
# Activo: 0x42 número de color 0..17; 0x43..0x46 rojo, verde, azul y blanco (0..255).
# Pasivo y crudo: desde 0x42, rojo, verde, azul y blanco de 16 bits, byte alto primero.
# Fuentes de cada registro en el README del paquete. Sin probar con el sensor real.
HTCOLOR_DIRECCION = 0x01
HTCOLOR_MODO = 0x41
HTCOLOR_DATOS = 0x42
HTCOLOR_MODOS = {"activo": 0, "pasivo": 1, "crudo": 3}
HTCOLOR_CANALES = {"rojo": 0, "verde": 1, "azul": 2, "blanco": 3}
htcolor_sensores = {}


def htcolor_i2c(puerto):
    # I2CDevice pone el puerto en modo other-i2c: quita el driver ht-nxt-color-v2 de ev3dev.
    return I2CDevice(puerto, HTCOLOR_DIRECCION)


def htcolor_configurar(puerto, modo, bloque):
    i2c = rb_device(puerto, htcolor_i2c, bloque)
    try:
        # Registros 0x08..0x0F: fabricante «HiTechnc», el mismo texto que reconoce ev3dev.
        fabricante = bytes(i2c.read(0x08, 8))
        if fabricante == b"HiTechnc":
            i2c.write(HTCOLOR_MODO, bytes((HTCOLOR_MODOS[modo],)))
            wait(100)
            # Primera lectura descartada (OFDL: tras un programa interrumpido repite el valor viejo).
            i2c.read(HTCOLOR_DATOS, 1)
    except OSError:
        rb_fail(bloque, "No responde el HiTechnic Color V2 (I2C 0x01)")
    if fabricante != b"HiTechnc":
        rb_fail(bloque, "El sensor del puerto no es un HiTechnic")
    htcolor_sensores[puerto] = [i2c, modo]


def htcolor(puerto, bloque):
    if puerto not in htcolor_sensores:
        rb_fail(bloque, "Configura el HT color de este puerto al iniciar")
    return htcolor_sensores[puerto]


def htcolor_leer(puerto, registro, cuantos, bloque):
    i2c = htcolor(puerto, bloque)[0]
    for intento in range(3):
        try:
            datos = i2c.read(registro, cuantos)
            if len(datos) == cuantos:
                return datos
        except OSError:
            pass
    rb_fail(bloque, "No responde el HiTechnic Color V2 (I2C 0x01)")


def htcolor_numero(puerto, bloque):
    if htcolor(puerto, bloque)[1] != "activo":
        rb_fail(bloque, "El número de color solo existe en modo activo")
    return htcolor_leer(puerto, HTCOLOR_DATOS, 1, bloque)[0]


def htcolor_canal(puerto, canal, bloque):
    indice = HTCOLOR_CANALES[canal]
    if htcolor(puerto, bloque)[1] == "activo":
        return htcolor_leer(puerto, HTCOLOR_DATOS + 1 + indice, 1, bloque)[0]
    datos = htcolor_leer(puerto, HTCOLOR_DATOS + 2 * indice, 2, bloque)
    return datos[0] << 8 | datos[1]


def htcolor_ve(puerto, numero, bloque):
    return htcolor_numero(puerto, bloque) == numero

